async fn function0(n:i64,seed:i64)->i64{let directory=std::env::var("TSRUST_COMPRESSION_INPUT_DIR").unwrap();let payload=std::fs::read(format!("{directory}/random-{seed}-plain.bin")).unwrap();let pool=tsrust_native_threads::create_pool(1,1).unwrap();if n== -1{let input=payload.clone();let output=match tsrust_native_threads::task_async(pool.submission(),move||Ok::<_,std::convert::Infallible>(tsrust_native_compression::buffer(input,tsrust_native_compression::Format::Raw,tsrust_native_compression::Direction::Encode,None,"deflateRaw"))).await{Ok(Ok(value))=>value,_=>panic!("codec/pool failure")};std::fs::write(std::env::var("TSRUST_COMPRESSION_PROBE_OUTPUT").unwrap(),&output).unwrap();pool.shutdown().unwrap();return output.len()as i64;}let mut sum=0;for _ in 0..n{let input=payload.clone();let output=match tsrust_native_threads::task_async(pool.submission(),move||Ok::<_,std::convert::Infallible>(tsrust_native_compression::buffer(input,tsrust_native_compression::Format::Raw,tsrust_native_compression::Direction::Encode,None,"deflateRaw"))).await{Ok(Ok(value))=>value,_=>panic!("codec/pool failure")};let decoded=match tsrust_native_threads::task_async(pool.submission(),move||Ok::<_,std::convert::Infallible>(tsrust_native_compression::buffer(output,tsrust_native_compression::Format::Raw,tsrust_native_compression::Direction::Decode,None,"inflateRaw"))).await{Ok(Ok(value))=>value,_=>panic!("codec/pool failure")};assert_eq!(decoded.len(),16384);for value in decoded{sum=(sum*131+i64::from(value))%1000000007;}}pool.shutdown().unwrap();sum}fn main(){}
